{{-- Company intro video (the TV advert with voice-over): it starts muted, as browsers require for autoplay; "Sound on" restarts it with sound. Button behaviour in site.js. --}}
<div class="who-video"><video src="/videos/intro.mp4?v=4" poster="/videos/intro-poster.webp?v=4" autoplay muted loop playsinline preload="metadata" aria-label="GTech Digital company introduction video"></video><button class="who-sound" type="button" aria-label="Turn sound on" aria-pressed="false" data-video-sound>@icon('lucide:volume-x', 18)<span>Sound on</span><template>@icon('lucide:volume-2', 18)</template></button><button class="who-play" type="button" aria-label="Pause video" data-video-toggle>@icon('lucide:pause', 18)<template>@icon('lucide:play', 18)</template></button></div>
